using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class ModelTrainingService
{
    private readonly ILogger<ModelTrainingService> _logger;
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly MLContext _mlContext;

    public ModelTrainingService(ILogger<ModelTrainingService> logger, IWebHostEnvironment env)
    {
        _logger = logger;
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
        _mlContext = new MLContext(seed: 42);
    }

    public EvaluationResult TrainModel()
    {
        _logger.LogInformation("Loading data from {Path}", _dataPath);

        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Evaluate with train/test split
        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2);
        var pipeline = BuildPipeline();

        var trainedModel = pipeline.Fit(split.TrainSet);
        var predictions = trainedModel.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        _logger.LogInformation("Train/Test Split Metrics:");
        _logger.LogInformation("  LogLoss:       {LogLoss:F4}", metrics.LogLoss);
        _logger.LogInformation("  MacroAccuracy: {MacroAccuracy:F4}", metrics.MacroAccuracy);
        _logger.LogInformation("  MicroAccuracy: {MicroAccuracy:F4}", metrics.MicroAccuracy);

        // Retrain on full data for the production model
        var fullModel = pipeline.Fit(data);
        _mlContext.Model.Save(fullModel, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);

        return new EvaluationResult
        {
            LogLoss = metrics.LogLoss,
            MacroAccuracy = metrics.MacroAccuracy,
            MicroAccuracy = metrics.MicroAccuracy
        };
    }

    private IEstimator<ITransformer> BuildPipeline()
    {
        return _mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Conversion.ConvertType(nameof(TicketInput.Priority), nameof(TicketInput.Priority)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
            .Append(_mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
    }
}

public class EvaluationResult
{
    public double LogLoss { get; set; }
    public double MacroAccuracy { get; set; }
    public double MicroAccuracy { get; set; }
}

namespace TicketClassifier.Models;

public class PredictRequest
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; }
}

public class PredictResponse
{
    public string PredictedCategory { get; set; } = string.Empty;
    public Dictionary<string, float> ConfidenceScores { get; set; } = new();
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class PredictController : ControllerBase
{
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;

    public PredictController(PredictionEnginePool<TicketInput, TicketPrediction> predictionPool)
    {
        _predictionPool = predictionPool;
    }

    [HttpPost]
    public ActionResult<PredictResponse> Post([FromBody] PredictRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);

        var labels = new[] { "Billing", "General", "Technical" };
        var confidenceScores = new Dictionary<string, float>();
        for (var i = 0; i < prediction.Score.Length && i < labels.Length; i++)
        {
            confidenceScores[labels[i]] = prediction.Score[i];
        }

        return Ok(new PredictResponse
        {
            PredictedCategory = prediction.PredictedLabel,
            ConfidenceScores = confidenceScores
        });
    }
}

