         var trainedModel = pipeline.Fit(split.TrainSet);
         var predictions = trainedModel.Transform(split.TestSet);
         var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

         _logger.LogInformation("Train/Test Split Metrics:");
         _logger.LogInformation("  LogLoss:       {LogLoss:F4}", metrics.LogLoss);
         _logger.LogInformation("  MacroAccuracy: {MacroAccuracy:F4}", metrics.MacroAccuracy);
         _logger.LogInformation("  MicroAccuracy: {MicroAccuracy:F4}", metrics.MicroAccuracy);

         // Retrain on full data for the production model
         var fullModel = pipeline.Fit(data);
         _mlContext.Model.Save(fullModel, data.Schema, _modelPath);
         _logger.LogInformation("Model saved to {Path}", _modelPath);

         return new EvaluationResult
         {
             LogLoss = metrics.LogLoss,
             MacroAccuracy = metrics.MacroAccuracy,
             MicroAccuracy = metrics.MicroAccuracy
         };
     }

     private IEstimator<ITransformer> BuildPipeline()
     {
         return _mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject))
             .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
             .Append(_mlContext.Transforms.Conversion.ConvertType(nameof(TicketInput.Priority), nameof(TicketInput.Priority)))
             .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
             .Append(_mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category)))
             .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
             .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
     }
 }

 public class EvaluationResult
 {
     public double LogLoss { get; set; }
     public double MacroAccuracy { get; set; }
     public double MicroAccuracy { get; set; }
 }

